// QBShippingSameAsSales is the shipping select's value for "bill shipping
// against the same item as the products". Explicit rather than empty so the
// handler can tell it apart from a stale, disabled option being dropped by the
// browser.
const QBShippingSameAsSales = "same-as-sales"

// QBItemChoice is one selectable QuickBooks item.
type QBItemChoice struct {
	ID            string
	Name          string
	IncomeAccount string
}

// QBItemPanel backs the invoice-items picker.
//
// Unavailable and Choices being empty are different facts and are shown
// differently: a company genuinely without items is a data problem the shop
// can fix, while a failed listing says nothing about the company at all.
type QBItemPanel struct {
	SalesItemID      string
	SalesItemName    string
	ShippingItemID   string
	ShippingItemName string
	Choices          []QBItemChoice
	// Unavailable is set when the items could not be listed from QuickBooks.
	Unavailable bool
	// ConfigUnreadable is set when the stored choice itself could not be read.
	// Distinct from Unavailable: one means we cannot offer alternatives, the
	// other means we cannot say what is billing right now — and only the
	// second warrants telling staff that invoicing may be unconfigured.
	ConfigUnreadable bool
	// EnvFallback is an item id still coming from the environment. Shown only
	// when nothing has been chosen here, to explain what is billing meanwhile.
	EnvFallback string
}

// Configured reports whether invoices have an item to bill against, from
// either source.
func (p QBItemPanel) Configured() bool {
	return p.SalesItemID != "" || p.EnvFallback != ""
}

// SalesItemMissing reports that the configured item is not among the choices —
// deactivated in QuickBooks, most likely. Only meaningful once the choices
// were actually listed; a failed listing says nothing about what exists.
func (p QBItemPanel) SalesItemMissing() bool {
	return p.itemMissing(p.SalesItemID)
}

// ShippingItemMissing is SalesItemMissing for the shipping line.
func (p QBItemPanel) ShippingItemMissing() bool {
	return p.itemMissing(p.ShippingItemID)
}

func (p QBItemPanel) itemMissing(id string) bool {
	if id == "" || p.Unavailable || len(p.Choices) == 0 {
		return false
	}
	for _, choice := range p.Choices {
		if choice.ID == id {
			return false
		}
	}
	return true
}

// SalesItemLabel names the configured item, falling back to its id when the
// cached name is empty.
func (p QBItemPanel) SalesItemLabel() string {
	if p.SalesItemName != "" {
		return p.SalesItemName
	}
	return "Item " + p.SalesItemID
}

// ShippingItemLabel is SalesItemLabel for the shipping line.
func (p QBItemPanel) ShippingItemLabel() string {
	if p.ShippingItemName != "" {
		return p.ShippingItemName
	}
	return "Item " + p.ShippingItemID
}

